import { useEffect, useState } from "react";
import Loader from "react-loaders";
import AnimatedLetters from "../AnimatedLetters";
import useInView from "../../hooks/useInView";
import "./index.scss";

const projects = [
  {
    id: "draftkings",
    title: "DraftKings NBA Lineup Recommender",
    tagline: "Full-Stack • React • Node • CSV Parsing",
    description:
      "Full-stack tool that ingests DraftKings salary CSVs, calculates player efficiency, and generates optimized NBA lineups under the salary cap.",
    repoUrl: "https://github.com/capisz/draftkings-optimizer",
  },
  {
    id: "dragapultist",
    title: "Dragapultist – Pokémon TCG Analyzer",
    tagline: "Next.js • TypeScript • TCGdex API",
    description:
      "Deck analysis tool for Pokémon TCG Live that imports card IDs, uses the TCGdex SDK to fetch metadata, shuffles decks, simulates prize cards, and helps track matchups.",
    repoUrl: "https://github.com/capisz/dragapultist",
  },
  {
    id: "elephit",
    title: "Elephit – Dynamic Calorie Tracker",
    tagline: "Next.js • React • Form Logic",
    description:
      "A dynamic alternative to MyFitnessPal that adjusts calorie targets based on weight trends, rewarding consistency and adapting macros as the user’s body changes.",
    repoUrl: "https://github.com/capisz/elephit-fitness-app",
  },
];

const Portfolio = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  const [ref, inView] = useInView();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <div
        id="portfolio"
        ref={ref}
        className={`container portfolio-page fade-section ${
          inView ? "in-view" : ""
        }`}
      >
        <div className="text-zone">
          <h1>
            <AnimatedLetters
              letterClass={letterClass}
              strArray={"My Portfolio".split("")}
              index={15}
            />
          </h1>
          <p>
            A selection of full-stack and front-end projects that reflect how I
            like to build: practical, data-driven, and focused on real user
            workflows—from fantasy sports optimization, to dynamic fitness
            tracking, to tooling for the Pokémon TCG.
          </p>
        </div>

        <div className="projects-grid">
          {projects.map((project, index) => (
            <article
              key={project.id}
              className={`project-card project-${project.id}`}
              style={{ animationDelay: `${0.15 * index}s` }}
            >
              <div className="project-thumb" />
              <div className="project-content">
                <h3>{project.title}</h3>
                <p className="project-tagline">{project.tagline}</p>
                <p className="project-description">{project.description}</p>

                <div className="project-links">
                  <a
                    href={project.repoUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="flat-button small secondary"
                  >
                    VIEW CODE
                  </a>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>

      <Loader type="pacman" />
    </>
  );
};

export default Portfolio;
